# -*- coding: utf-8 -*-
CSS_CONTENT = '\n    :root {\n      --bg: #07090e;\n      --bg-card: rgba(14, 18, 27, 0.82);\n      --bg-card-hover: rgba(20, 26, 40, 0.96);\n      --border: rgba(255, 255, 255, 0.08);\n      --border-accent: rgba(0, 230, 118, 0.4);\n      --border-cyan: rgba(0, 229, 255, 0.35);\n      \n      --fg: #e6edf3;\n      --fg-muted: #8b949e;\n      --fg-subtle: #57606a;\n      \n      --accent-green: #00e676;\n      --accent-cyan: #00e5ff;\n      --accent-blue: #38bdf8;\n      --accent-amber: #ffd600;\n      --accent-purple: #b388ff;\n      \n      /* Pure Roboto Typography Hierarchy */\n      --font-sans: \'Roboto\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', sans-serif;\n      --font-display: \'Roboto Condensed\', \'Roboto\', sans-serif;\n      --font-slab: \'Roboto Slab\', serif;\n      --font-mono: \'Roboto Mono\', monospace;\n    }\n\n    * { margin: 0; padding: 0; box-sizing: border-box; }\n\n    body {\n      background-color: var(--bg);\n      color: var(--fg);\n      font-family: var(--font-sans);\n      font-weight: 400;\n      font-size: 16px;\n      line-height: 1.68;\n      overflow-x: hidden;\n      background-image: \n        radial-gradient(circle at 10% 10%, rgba(0, 230, 118, 0.05) 0%, transparent 40%),\n        radial-gradient(circle at 90% 15%, rgba(0, 229, 255, 0.04) 0%, transparent 45%),\n        radial-gradient(circle at 50% 85%, rgba(56, 189, 248, 0.03) 0%, transparent 50%);\n      background-attachment: fixed;\n    }\n\n    /* Fluid / Responsive Container */\n    .container {\n      width: 100%;\n      max-width: min(1540px, 94vw);\n      margin: 0 auto;\n      padding: clamp(24px, 4vw, 44px) clamp(16px, 3vw, 36px) 100px;\n    }\n\n    /* Navigation */\n    .nav-bar {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding-bottom: 22px;\n      border-bottom: 1px solid var(--border);\n      margin-bottom: clamp(32px, 5vw, 56px);\n      flex-wrap: wrap;\n      gap: 16px;\n    }\n\n    .brand {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      text-decoration: none;\n      color: #fff;\n      font-family: var(--font-display);\n      font-weight: 700;\n      font-size: 1.35rem;\n      letter-spacing: -0.01em;\n    }\n\n    .brand-logo {\n      width: 34px;\n      height: 34px;\n      background: linear-gradient(135deg, var(--accent-green), var(--accent-cyan));\n      border-radius: 8px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      color: #000;\n      font-family: var(--font-sans);\n      font-weight: 900;\n      font-size: 17px;\n    }\n\n    .nav-links {\n      display: flex;\n      gap: 20px;\n      align-items: center;\n      font-size: 0.94rem;\n      font-family: var(--font-sans);\n      font-weight: 500;\n      flex-wrap: wrap;\n    }\n\n    .nav-link {\n      color: var(--fg-muted);\n      text-decoration: none;\n      transition: color 0.2s;\n    }\n\n    .nav-link:hover {\n      color: var(--accent-green);\n    }\n\n    .cluster-badge {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      padding: 6px 14px;\n      background: rgba(0, 230, 118, 0.08);\n      border: 1px solid rgba(0, 230, 118, 0.28);\n      border-radius: 20px;\n      font-family: var(--font-mono);\n      font-size: 0.8rem;\n      font-weight: 500;\n      color: var(--accent-green);\n    }\n\n    .pulse-dot {\n      width: 8px;\n      height: 8px;\n      background: var(--accent-green);\n      border-radius: 50%;\n      box-shadow: 0 0 10px var(--accent-green);\n      animation: pulse 2s infinite;\n    }\n\n    @keyframes pulse {\n      0%, 100% { opacity: 1; transform: scale(1); }\n      50% { opacity: 0.4; transform: scale(0.85); }\n    }\n\n    /* Hero Section */\n    .hero {\n      margin-bottom: clamp(48px, 6vw, 72px);\n    }\n\n    .hero-eyebrow {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      font-family: var(--font-mono);\n      font-weight: 500;\n      color: var(--accent-cyan);\n      font-size: 0.84rem;\n      letter-spacing: 0.08em;\n      text-transform: uppercase;\n      margin-bottom: 18px;\n      padding: 5px 12px;\n      background: rgba(0, 229, 255, 0.08);\n      border: 1px solid rgba(0, 229, 255, 0.22);\n      border-radius: 4px;\n    }\n\n    .hero-title {\n      font-family: var(--font-display);\n      font-size: clamp(2.4rem, 5.5vw, 4.2rem);\n      font-weight: 700;\n      line-height: 1.12;\n      letter-spacing: -0.02em;\n      margin-bottom: 24px;\n      color: #ffffff;\n    }\n\n    .hero-title span {\n      background: linear-gradient(135deg, #ffffff 30%, var(--accent-cyan) 100%);\n      -webkit-background-clip: text;\n      -webkit-text-fill-color: transparent;\n    }\n\n    .hero-subtitle {\n      font-family: var(--font-sans);\n      font-weight: 300;\n      font-size: clamp(1.15rem, 2vw, 1.35rem);\n      color: #b8c4d4;\n      max-width: 1040px;\n      line-height: 1.65;\n      margin-bottom: 36px;\n    }\n\n    .key-facts-bar {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr));\n      gap: 16px;\n      padding: 24px;\n      background: var(--bg-card);\n      border: 1px solid var(--border);\n      border-radius: 14px;\n      backdrop-filter: blur(14px);\n    }\n\n    .fact-item {\n      display: flex;\n      flex-direction: column;\n      gap: 4px;\n    }\n\n    .fact-value {\n      font-family: var(--font-display);\n      font-size: clamp(1.6rem, 2.5vw, 2.1rem);\n      font-weight: 700;\n      color: #fff;\n    }\n\n    .fact-value.green { color: var(--accent-green); }\n    .fact-value.cyan { color: var(--accent-cyan); }\n    .fact-value.amber { color: var(--accent-amber); }\n    .fact-value.purple { color: var(--accent-purple); }\n\n    .fact-label {\n      font-family: var(--font-sans);\n      font-weight: 400;\n      font-size: 0.82rem;\n      color: var(--fg-muted);\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n    }\n\n    /* Content Sections */\n    .section {\n      margin-bottom: clamp(56px, 7vw, 84px);\n    }\n\n    .section-header {\n      display: flex;\n      align-items: center;\n      gap: 16px;\n      margin-bottom: 24px;\n      flex-wrap: wrap;\n    }\n\n    .section-num {\n      font-family: var(--font-mono);\n      font-size: 0.95rem;\n      font-weight: 600;\n      color: var(--accent-green);\n      padding: 4px 10px;\n      background: rgba(0, 230, 118, 0.08);\n      border: 1px solid rgba(0, 230, 118, 0.2);\n      border-radius: 6px;\n    }\n\n    .section-title {\n      font-family: var(--font-display);\n      font-size: clamp(1.8rem, 3vw, 2.5rem);\n      font-weight: 700;\n      letter-spacing: -0.01em;\n      color: #fff;\n    }\n\n    .lead-text {\n      font-size: clamp(1.1rem, 1.8vw, 1.25rem);\n      color: #d1d8e5;\n      font-weight: 400;\n      line-height: 1.7;\n      margin-bottom: 22px;\n    }\n\n    p {\n      margin-bottom: 18px;\n      color: #9aa5b5;\n      font-size: 1.02rem;\n      line-height: 1.7;\n    }\n\n    p strong {\n      color: #ffffff;\n      font-weight: 600;\n    }\n\n    /* Fluid Cards Grid */\n    .cards-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(min(100%, 340px), 1fr));\n      gap: clamp(16px, 2vw, 24px);\n      margin: 28px 0;\n    }\n\n    .card {\n      background: var(--bg-card);\n      border: 1px solid var(--border);\n      border-radius: 12px;\n      padding: clamp(20px, 3vw, 28px);\n      transition: transform 0.2s, border-color 0.2s, background 0.2s;\n      backdrop-filter: blur(10px);\n      display: flex;\n      flex-direction: column;\n    }\n\n    .card:hover {\n      transform: translateY(-2px);\n      border-color: var(--border-accent);\n      background: var(--bg-card-hover);\n    }\n\n    .card-icon {\n      font-size: 2rem;\n      margin-bottom: 16px;\n    }\n\n    .card-title {\n      font-family: var(--font-display);\n      font-size: 1.3rem;\n      font-weight: 700;\n      color: #fff;\n      margin-bottom: 12px;\n    }\n\n    .card-text {\n      font-size: 0.96rem;\n      color: #9aa5b5;\n      line-height: 1.65;\n      margin-bottom: 0;\n      flex-grow: 1;\n    }\n\n    /* Workflow Diagram Container */\n    .workflow-container {\n      background: var(--bg-card);\n      border: 1px solid var(--border);\n      border-radius: 14px;\n      padding: clamp(22px, 3vw, 36px);\n      margin: 32px 0;\n    }\n\n    .workflow-header {\n      font-family: var(--font-display);\n      font-size: 1.4rem;\n      font-weight: 700;\n      color: #fff;\n      margin-bottom: 8px;\n    }\n\n    .workflow-sub {\n      font-size: 0.94rem;\n      color: var(--fg-muted);\n      margin-bottom: 24px;\n    }\n\n    .workflow-steps {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));\n      gap: 16px;\n    }\n\n    .step-box {\n      background: rgba(255, 255, 255, 0.03);\n      border: 1px solid rgba(255, 255, 255, 0.07);\n      border-radius: 8px;\n      padding: 22px;\n    }\n\n    .step-num {\n      font-family: var(--font-mono);\n      font-size: 0.78rem;\n      font-weight: 600;\n      color: var(--accent-cyan);\n      letter-spacing: 0.06em;\n      margin-bottom: 8px;\n      text-transform: uppercase;\n    }\n\n    .step-title {\n      font-family: var(--font-display);\n      font-size: 1.15rem;\n      font-weight: 700;\n      color: #fff;\n      margin-bottom: 8px;\n    }\n\n    .step-desc {\n      font-size: 0.9rem;\n      color: #9aa5b5;\n      line-height: 1.55;\n      margin-bottom: 0;\n    }\n\n    /* Callout Box */\n    .callout {\n      padding: clamp(20px, 3vw, 28px);\n      background: rgba(0, 229, 255, 0.04);\n      border: 1px solid rgba(0, 229, 255, 0.2);\n      border-left: 4px solid var(--accent-cyan);\n      border-radius: 8px;\n      margin: 32px 0;\n    }\n\n    .callout-title {\n      font-family: var(--font-display);\n      font-size: 1.25rem;\n      font-weight: 700;\n      color: var(--accent-cyan);\n      margin-bottom: 8px;\n    }\n\n    .callout-body {\n      color: #d1d8e5;\n      font-size: 1.02rem;\n      line-height: 1.65;\n      margin: 0;\n    }\n\n    /* Production Specs Box */\n    .production-box {\n      background: var(--bg-card);\n      border: 1px solid rgba(0, 230, 118, 0.25);\n      border-radius: 14px;\n      padding: clamp(22px, 3vw, 36px);\n      margin: 32px 0;\n    }\n\n    .production-header {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      margin-bottom: 16px;\n    }\n\n    .production-badge {\n      font-family: var(--font-mono);\n      font-size: 0.8rem;\n      padding: 4px 10px;\n      background: rgba(0, 230, 118, 0.12);\n      color: var(--accent-green);\n      border: 1px solid rgba(0, 230, 118, 0.3);\n      border-radius: 4px;\n      font-weight: 600;\n    }\n\n    /* Models Matrix Interactive UI */\n    .matrix-controls {\n      background: var(--bg-card);\n      border: 1px solid var(--border);\n      border-radius: 14px;\n      padding: clamp(18px, 3vw, 26px);\n      margin-bottom: 24px;\n      display: flex;\n      flex-direction: column;\n      gap: 18px;\n      backdrop-filter: blur(12px);\n    }\n\n    .matrix-tabs {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 12px;\n      padding-bottom: 16px;\n      border-bottom: 1px solid var(--border);\n    }\n\n    .matrix-tab {\n      background: rgba(255, 255, 255, 0.04);\n      border: 1px solid var(--border);\n      color: var(--fg-muted);\n      padding: 10px 20px;\n      border-radius: 8px;\n      font-family: var(--font-display);\n      font-size: 1.05rem;\n      font-weight: 700;\n      cursor: pointer;\n      transition: all 0.2s;\n    }\n\n    .matrix-tab:hover {\n      background: rgba(255, 255, 255, 0.08);\n      color: #fff;\n    }\n\n    .matrix-tab.active[data-filter="free"] {\n      background: rgba(0, 230, 118, 0.15);\n      border-color: var(--accent-green);\n      color: var(--accent-green);\n      box-shadow: 0 0 16px rgba(0, 230, 118, 0.2);\n    }\n\n    .matrix-tab.active[data-filter="paid"] {\n      background: rgba(0, 229, 255, 0.15);\n      border-color: var(--accent-cyan);\n      color: var(--accent-cyan);\n      box-shadow: 0 0 16px rgba(0, 229, 255, 0.2);\n    }\n\n    .matrix-tab.active[data-filter="all"] {\n      background: rgba(179, 136, 255, 0.15);\n      border-color: var(--accent-purple);\n      color: #fff;\n      box-shadow: 0 0 16px rgba(179, 136, 255, 0.2);\n    }\n\n    .matrix-sort-bar {\n      display: flex;\n      align-items: center;\n      flex-wrap: wrap;\n      gap: 10px;\n    }\n\n    .sort-label {\n      font-family: var(--font-mono);\n      font-size: 0.82rem;\n      color: var(--fg-muted);\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n      margin-right: 4px;\n      font-weight: 500;\n    }\n\n    .sort-btn {\n      background: rgba(255, 255, 255, 0.03);\n      border: 1px solid var(--border);\n      color: var(--fg-muted);\n      padding: 7px 16px;\n      border-radius: 6px;\n      font-size: 0.88rem;\n      font-family: var(--font-sans);\n      font-weight: 500;\n      cursor: pointer;\n      transition: all 0.2s;\n    }\n\n    .sort-btn:hover {\n      background: rgba(255, 255, 255, 0.08);\n      color: #fff;\n    }\n\n    .sort-btn.active {\n      background: rgba(56, 189, 248, 0.15);\n      border-color: var(--accent-blue);\n      color: #fff;\n    }\n\n    .matrix-search-box {\n      display: flex;\n      align-items: center;\n      gap: 14px;\n      flex-wrap: wrap;\n    }\n\n    .matrix-search-box input {\n      flex: 1;\n      min-width: 260px;\n      background: rgba(0, 0, 0, 0.4);\n      border: 1px solid var(--border);\n      border-radius: 8px;\n      padding: 12px 18px;\n      color: #fff;\n      font-family: var(--font-sans);\n      font-size: 0.95rem;\n      outline: none;\n      transition: border-color 0.2s;\n    }\n\n    .matrix-search-box input:focus {\n      border-color: var(--accent-cyan);\n    }\n\n    .count-badge {\n      font-family: var(--font-mono);\n      font-size: 0.84rem;\n      color: var(--accent-green);\n      background: rgba(0, 230, 118, 0.08);\n      border: 1px solid rgba(0, 230, 118, 0.2);\n      padding: 8px 14px;\n      border-radius: 6px;\n      white-space: nowrap;\n      font-weight: 500;\n    }\n\n    /* Responsive Models Grid */\n    .models-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(min(100%, 330px), 1fr));\n      gap: 18px;\n      margin-top: 16px;\n    }\n\n    .model-card {\n      background: var(--bg-card);\n      border: 1px solid var(--border);\n      border-radius: 12px;\n      padding: 22px;\n      display: flex;\n      flex-direction: column;\n      gap: 14px;\n      transition: all 0.2s;\n      position: relative;\n    }\n\n    .model-card:hover {\n      transform: translateY(-2px);\n      border-color: var(--border-accent);\n      background: var(--bg-card-hover);\n    }\n\n    .model-card.is-paid:hover {\n      border-color: var(--border-cyan);\n    }\n\n    .model-card-header {\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-start;\n      gap: 12px;\n    }\n\n    .model-name {\n      font-family: var(--font-display);\n      font-size: 1.2rem;\n      font-weight: 700;\n      color: #fff;\n      line-height: 1.3;\n    }\n\n    .provider-badge {\n      font-family: var(--font-mono);\n      font-size: 0.74rem;\n      padding: 4px 8px;\n      border-radius: 4px;\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n      white-space: nowrap;\n      font-weight: 600;\n    }\n\n    .provider-google { background: rgba(66, 133, 244, 0.15); color: #60a5fa; border: 1px solid rgba(66, 133, 244, 0.3); }\n    .provider-anthropic { background: rgba(217, 119, 6, 0.15); color: #fbbf24; border: 1px solid rgba(217, 119, 6, 0.3); }\n    .provider-deepseek { background: rgba(14, 165, 233, 0.15); color: #38bdf8; border: 1px solid rgba(14, 165, 233, 0.3); }\n    .provider-openai { background: rgba(16, 185, 129, 0.15); color: #34d399; border: 1px solid rgba(16, 185, 129, 0.3); }\n    .provider-meta { background: rgba(168, 85, 247, 0.15); color: #c084fc; border: 1px solid rgba(168, 85, 247, 0.3); }\n    .provider-mistral { background: rgba(245, 158, 11, 0.15); color: #f59e0b; border: 1px solid rgba(245, 158, 11, 0.3); }\n    .provider-omniroute { background: rgba(0, 230, 118, 0.15); color: var(--accent-green); border: 1px solid rgba(0, 230, 118, 0.3); }\n    .provider-default { background: rgba(255, 255, 255, 0.1); color: #e6edf3; border: 1px solid var(--border); }\n\n    .model-metrics {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 8px;\n    }\n\n    .metric-pill {\n      font-family: var(--font-mono);\n      font-size: 0.76rem;\n      padding: 3px 8px;\n      border-radius: 4px;\n      background: rgba(255, 255, 255, 0.04);\n      border: 1px solid rgba(255, 255, 255, 0.07);\n      color: var(--fg-muted);\n    }\n\n    .metric-pill strong {\n      color: #fff;\n    }\n\n    .metric-pill.iq {\n      background: rgba(0, 229, 255, 0.08);\n      border-color: rgba(0, 229, 255, 0.25);\n      color: var(--accent-cyan);\n    }\n\n    .metric-pill.tier-free {\n      background: rgba(0, 230, 118, 0.08);\n      border-color: rgba(0, 230, 118, 0.25);\n      color: var(--accent-green);\n    }\n\n    .metric-pill.tier-paid {\n      background: rgba(179, 136, 255, 0.08);\n      border-color: rgba(179, 136, 255, 0.25);\n      color: var(--accent-purple);\n    }\n\n    .model-desc {\n      font-size: 0.9rem;\n      color: #9aa5b5;\n      line-height: 1.55;\n      margin-bottom: 0;\n      flex-grow: 1;\n    }\n\n    .model-role {\n      font-size: 0.84rem;\n      color: #cbd5e1;\n      background: rgba(255, 255, 255, 0.03);\n      border-left: 3px solid var(--accent-cyan);\n      padding: 8px 12px;\n      border-radius: 0 6px 6px 0;\n    }\n\n    .model-pricing-box {\n      display: flex;\n      flex-direction: column;\n      gap: 4px;\n      padding-top: 10px;\n      border-top: 1px solid rgba(255, 255, 255, 0.05);\n      font-family: var(--font-mono);\n      font-size: 0.78rem;\n    }\n\n    .price-tag {\n      font-weight: 700;\n      color: #fff;\n    }\n\n    .price-tag.free { color: var(--accent-green); }\n    .price-tag.paid { color: var(--accent-cyan); }\n\n    /* Comparison Table */\n    .table-container {\n      overflow-x: auto;\n      margin: 32px 0;\n      border: 1px solid var(--border);\n      border-radius: 14px;\n      background: var(--bg-card);\n    }\n\n    table {\n      width: 100%;\n      border-collapse: collapse;\n      text-align: left;\n      font-size: 0.94rem;\n    }\n\n    th {\n      background: rgba(255, 255, 255, 0.03);\n      color: var(--fg-muted);\n      font-family: var(--font-mono);\n      font-size: 0.82rem;\n      font-weight: 600;\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n      padding: 16px 20px;\n      border-bottom: 1px solid var(--border);\n    }\n\n    td {\n      padding: 16px 20px;\n      border-bottom: 1px solid rgba(255, 255, 255, 0.04);\n      color: #9aa5b5;\n      vertical-align: top;\n    }\n\n    tr:last-child td {\n      border-bottom: none;\n    }\n\n    td strong {\n      color: #fff;\n    }\n\n    .col-highlight {\n      color: var(--accent-green);\n      font-weight: 500;\n    }\n\n    /* Hub Links */\n    .hub-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr));\n      gap: 16px;\n      margin: 28px 0;\n    }\n\n    .hub-item {\n      display: flex;\n      flex-direction: column;\n      padding: 22px;\n      background: var(--bg-card);\n      border: 1px solid var(--border);\n      border-radius: 10px;\n      text-decoration: none;\n      color: inherit;\n      transition: all 0.2s;\n    }\n\n    .hub-item:hover {\n      border-color: var(--accent-green);\n      transform: translateY(-2px);\n    }\n\n    .hub-item-badge {\n      font-family: var(--font-mono);\n      font-size: 0.74rem;\n      color: var(--accent-green);\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n      margin-bottom: 8px;\n      font-weight: 600;\n    }\n\n    .hub-item-domain {\n      font-family: var(--font-display);\n      font-size: 1.25rem;\n      font-weight: 700;\n      color: #fff;\n      margin-bottom: 6px;\n    }\n\n    .hub-item-desc {\n      font-size: 0.88rem;\n      color: var(--fg-muted);\n      line-height: 1.48;\n    }\n\n    /* Footer */\n    footer {\n      margin-top: 60px;\n      padding-top: 40px;\n      border-top: 1px solid var(--border);\n      text-align: center;\n      color: var(--fg-subtle);\n      font-size: 0.88rem;\n      font-family: var(--font-mono);\n      line-height: 1.6;\n    }\n\n    footer a {\n      color: var(--fg-muted);\n      text-decoration: none;\n    }\n\n    footer a:hover {\n      color: var(--accent-green);\n    }\n\n    \n    /* Glossary Section */\n    .glossary-controls {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 12px;\n      align-items: center;\n      justify-content: space-between;\n      margin: 24px 0 20px;\n    }\n\n    .glossary-tabs {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 8px;\n    }\n\n    .glossary-tab {\n      background: var(--bg-card);\n      border: 1px solid var(--border);\n      color: var(--fg-muted);\n      font-family: var(--font-body);\n      font-size: 0.88rem;\n      padding: 8px 16px;\n      border-radius: 8px;\n      cursor: pointer;\n      transition: all 0.2s;\n    }\n\n    .glossary-tab:hover, .glossary-tab.active {\n      color: #fff;\n      border-color: var(--accent-green);\n      background: rgba(0, 230, 118, 0.12);\n    }\n\n    .glossary-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(min(100%, 340px), 1fr));\n      gap: clamp(16px, 2vw, 22px);\n      margin-top: 20px;\n    }\n\n    .glossary-card {\n      background: var(--bg-card);\n      border: 1px solid var(--border);\n      border-radius: 12px;\n      padding: clamp(20px, 2.5vw, 26px);\n      display: flex;\n      flex-direction: column;\n      gap: 12px;\n      transition: transform 0.2s, border-color 0.2s, background 0.2s;\n      position: relative;\n    }\n\n    .glossary-card:hover {\n      transform: translateY(-2px);\n      border-color: var(--border-accent);\n      background: var(--bg-card-hover);\n    }\n\n    .glossary-header {\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-start;\n      gap: 12px;\n    }\n\n    .glossary-term {\n      font-family: var(--font-display);\n      font-size: 1.25rem;\n      font-weight: 700;\n      color: #fff;\n      line-height: 1.3;\n    }\n\n    .glossary-category-pill {\n      font-family: var(--font-mono);\n      font-size: 0.72rem;\n      font-weight: 600;\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n      padding: 4px 8px;\n      border-radius: 4px;\n      white-space: nowrap;\n    }\n\n    .cat-ai {\n      background: rgba(56, 189, 248, 0.12);\n      color: var(--accent-blue);\n      border: 1px solid rgba(56, 189, 248, 0.3);\n    }\n\n    .cat-poly {\n      background: rgba(0, 230, 118, 0.12);\n      color: var(--accent-green);\n      border: 1px solid rgba(0, 230, 118, 0.3);\n    }\n\n    .cat-sec {\n      background: rgba(255, 214, 0, 0.12);\n      color: var(--accent-amber);\n      border: 1px solid rgba(255, 214, 0, 0.3);\n    }\n\n    .glossary-plain {\n      font-size: 0.98rem;\n      color: #c9d1d9;\n      line-height: 1.65;\n      background: rgba(255, 255, 255, 0.02);\n      border-left: 3px solid var(--accent-green);\n      padding: 10px 14px;\n      border-radius: 0 6px 6px 0;\n    }\n\n    .glossary-plain strong {\n      color: var(--accent-green);\n    }\n\n    .glossary-tech {\n      font-size: 0.88rem;\n      color: var(--fg-muted);\n      line-height: 1.55;\n    }\n\n    \n    /* ==========================================================================\n       SECTION 08: BUSINESS SOLUTIONS, PIPELINE & ROI CALCULATOR STYLES\n       ========================================================================== */\n    .biz-highlight-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(min(100%, 340px), 1fr));\n      gap: clamp(16px, 2vw, 24px);\n      margin: 28px 0;\n    }\n\n    .biz-card {\n      background: var(--bg-card);\n      border: 1px solid var(--border);\n      border-radius: 12px;\n      padding: clamp(20px, 2.5vw, 26px);\n      display: flex;\n      flex-direction: column;\n      gap: 14px;\n      transition: transform 0.2s, border-color 0.2s, background 0.2s;\n      position: relative;\n    }\n\n    .biz-card:hover {\n      transform: translateY(-2px);\n      border-color: var(--accent-cyan);\n      background: var(--bg-card-hover);\n    }\n\n    .biz-card-header {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n\n    .biz-card-icon {\n      font-size: 1.8rem;\n      line-height: 1;\n      padding: 10px;\n      background: rgba(0, 229, 255, 0.08);\n      border: 1px solid rgba(0, 229, 255, 0.2);\n      border-radius: 10px;\n      color: var(--accent-cyan);\n    }\n\n    .biz-card-title {\n      font-family: var(--font-display);\n      font-size: 1.25rem;\n      font-weight: 700;\n      color: #fff;\n    }\n\n    .biz-pain-box {\n      background: rgba(255, 23, 68, 0.06);\n      border-left: 3px solid var(--accent-red);\n      padding: 10px 14px;\n      border-radius: 0 6px 6px 0;\n      font-size: 0.92rem;\n      color: #f87171;\n    }\n\n    .biz-solution-box {\n      background: rgba(0, 230, 118, 0.06);\n      border-left: 3px solid var(--accent-green);\n      padding: 10px 14px;\n      border-radius: 0 6px 6px 0;\n      font-size: 0.92rem;\n      color: #e2e8f0;\n      line-height: 1.6;\n    }\n\n    .biz-solution-box strong {\n      color: var(--accent-green);\n    }\n\n    /* Pipeline Flow Infographic */\n    .pipeline-wrapper {\n      background: var(--bg-card);\n      border: 1px solid var(--border);\n      border-radius: 14px;\n      padding: clamp(20px, 3vw, 32px);\n      margin: 32px 0;\n    }\n\n    .pipeline-title-box {\n      text-align: center;\n      margin-bottom: 24px;\n    }\n\n    .pipeline-title-box h3 {\n      font-family: var(--font-display);\n      font-size: clamp(1.3rem, 2.2vw, 1.8rem);\n      color: #fff;\n      margin-bottom: 8px;\n    }\n\n    .pipeline-flow {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr));\n      gap: 16px;\n      position: relative;\n    }\n\n    .pipe-step {\n      background: rgba(14, 18, 27, 0.9);\n      border: 1px solid var(--border);\n      border-radius: 10px;\n      padding: 18px;\n      position: relative;\n      display: flex;\n      flex-direction: column;\n      gap: 10px;\n      transition: all 0.2s;\n    }\n\n    .pipe-step:hover {\n      border-color: var(--accent-green);\n      transform: translateY(-2px);\n    }\n\n    .pipe-badge {\n      font-family: var(--font-mono);\n      font-size: 0.75rem;\n      font-weight: 700;\n      color: var(--accent-green);\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n    }\n\n    .pipe-name {\n      font-family: var(--font-display);\n      font-size: 1.1rem;\n      font-weight: 700;\n      color: #fff;\n    }\n\n    .pipe-desc {\n      font-size: 0.88rem;\n      color: var(--fg-muted);\n      line-height: 1.5;\n    }\n\n    .pipe-tech {\n      font-family: var(--font-mono);\n      font-size: 0.76rem;\n      color: var(--accent-cyan);\n      background: rgba(0, 229, 255, 0.06);\n      padding: 4px 8px;\n      border-radius: 4px;\n      border: 1px solid rgba(0, 229, 255, 0.15);\n      margin-top: auto;\n    }\n\n    /* Before vs After Comparison Grid */\n    .compare-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr));\n      gap: 18px;\n      margin: 28px 0;\n    }\n\n    .compare-card {\n      background: var(--bg-card);\n      border: 1px solid var(--border);\n      border-radius: 12px;\n      padding: 22px;\n      display: flex;\n      flex-direction: column;\n      gap: 12px;\n    }\n\n    .compare-metric-title {\n      font-family: var(--font-display);\n      font-size: 1.15rem;\n      font-weight: 700;\n      color: #fff;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n    }\n\n    .compare-delta {\n      font-family: var(--font-mono);\n      font-size: 0.85rem;\n      font-weight: 700;\n      color: var(--accent-green);\n      background: rgba(0, 230, 118, 0.12);\n      border: 1px solid rgba(0, 230, 118, 0.3);\n      padding: 3px 8px;\n      border-radius: 6px;\n    }\n\n    .compare-row {\n      display: flex;\n      justify-content: space-between;\n      font-size: 0.92rem;\n      padding: 6px 0;\n      border-bottom: 1px solid rgba(255, 255, 255, 0.05);\n    }\n\n    .compare-row.before span:last-child {\n      color: #f87171;\n      font-weight: 600;\n    }\n\n    .compare-row.after span:last-child {\n      color: var(--accent-green);\n      font-weight: 700;\n    }\n\n    .compare-bar-wrap {\n      width: 100%;\n      height: 8px;\n      background: rgba(255, 255, 255, 0.08);\n      border-radius: 4px;\n      overflow: hidden;\n      margin-top: 6px;\n      position: relative;\n    }\n\n    .compare-bar-fill {\n      height: 100%;\n      background: linear-gradient(90deg, var(--accent-green), var(--accent-cyan));\n      border-radius: 4px;\n      transition: width 0.8s ease;\n    }\n\n    /* Interactive ROI Calculator */\n    .roi-calc-box {\n      background: linear-gradient(145deg, rgba(14, 18, 27, 0.95), rgba(9, 12, 19, 0.95));\n      border: 1px solid rgba(0, 230, 118, 0.3);\n      box-shadow: 0 10px 40px rgba(0, 0, 0, 0.4);\n      border-radius: 16px;\n      padding: clamp(24px, 3.5vw, 36px);\n      margin: 36px 0;\n    }\n\n    .roi-calc-header {\n      display: flex;\n      flex-wrap: wrap;\n      justify-content: space-between;\n      align-items: center;\n      gap: 16px;\n      margin-bottom: 28px;\n      border-bottom: 1px solid var(--border);\n      padding-bottom: 20px;\n    }\n\n    .roi-calc-header h3 {\n      font-family: var(--font-display);\n      font-size: clamp(1.4rem, 2.5vw, 2rem);\n      color: #fff;\n      margin: 0;\n    }\n\n    .roi-badge {\n      font-family: var(--font-mono);\n      font-size: 0.84rem;\n      background: rgba(0, 230, 118, 0.12);\n      border: 1px solid rgba(0, 230, 118, 0.3);\n      color: var(--accent-green);\n      padding: 6px 12px;\n      border-radius: 6px;\n    }\n\n    .roi-layout {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(min(100%, 340px), 1fr));\n      gap: 32px;\n    }\n\n    .roi-sliders {\n      display: flex;\n      flex-direction: column;\n      gap: 22px;\n    }\n\n    .roi-field {\n      display: flex;\n      flex-direction: column;\n      gap: 8px;\n    }\n\n    .roi-field-header {\n      display: flex;\n      justify-content: space-between;\n      font-size: 0.95rem;\n      color: #cbd5e1;\n    }\n\n    .roi-field-val {\n      font-family: var(--font-mono);\n      font-weight: 700;\n      color: var(--accent-cyan);\n    }\n\n    .roi-slider {\n      -webkit-appearance: none;\n      width: 100%;\n      height: 7px;\n      background: rgba(255, 255, 255, 0.1);\n      border-radius: 4px;\n      outline: none;\n      transition: background 0.2s;\n    }\n\n    .roi-slider::-webkit-slider-thumb {\n      -webkit-appearance: none;\n      width: 20px;\n      height: 20px;\n      border-radius: 50%;\n      background: var(--accent-green);\n      cursor: pointer;\n      box-shadow: 0 0 10px rgba(0, 230, 118, 0.6);\n      transition: transform 0.1s;\n    }\n\n    .roi-slider::-webkit-slider-thumb:hover {\n      transform: scale(1.2);\n    }\n\n    .roi-results-grid {\n      display: grid;\n      grid-template-columns: repeat(2, 1fr);\n      gap: 16px;\n    }\n\n    .roi-result-card {\n      background: rgba(0, 0, 0, 0.35);\n      border: 1px solid var(--border);\n      border-radius: 10px;\n      padding: 16px;\n      display: flex;\n      flex-direction: column;\n      gap: 6px;\n    }\n\n    .roi-result-label {\n      font-size: 0.84rem;\n      color: var(--fg-muted);\n    }\n\n    .roi-result-val {\n      font-family: var(--font-display);\n      font-size: clamp(1.4rem, 2.2vw, 1.8rem);\n      font-weight: 700;\n      color: #fff;\n    }\n\n    .roi-result-val.green { color: var(--accent-green); }\n    .roi-result-val.cyan { color: var(--accent-cyan); }\n    .roi-result-val.amber { color: var(--accent-amber); }\n\n    /* 5-Phase Onboarding Pipeline */\n    .phase-timeline {\n      display: flex;\n      flex-direction: column;\n      gap: 18px;\n      margin: 28px 0;\n    }\n\n    .phase-card {\n      background: var(--bg-card);\n      border: 1px solid var(--border);\n      border-radius: 12px;\n      padding: clamp(18px, 2vw, 24px);\n      display: grid;\n      grid-template-columns: auto 1fr;\n      gap: 20px;\n      align-items: flex-start;\n      transition: all 0.2s;\n    }\n\n    .phase-card:hover {\n      border-color: var(--accent-green);\n      background: var(--bg-card-hover);\n    }\n\n    .phase-badge-col {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      gap: 6px;\n    }\n\n    .phase-circle {\n      width: 44px;\n      height: 44px;\n      border-radius: 50%;\n      background: rgba(0, 230, 118, 0.1);\n      border: 2px solid var(--accent-green);\n      color: var(--accent-green);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-family: var(--font-mono);\n      font-weight: 700;\n      font-size: 1.1rem;\n    }\n\n    .phase-days {\n      font-family: var(--font-mono);\n      font-size: 0.72rem;\n      color: var(--fg-subtle);\n      white-space: nowrap;\n    }\n\n    .phase-body h4 {\n      font-family: var(--font-display);\n      font-size: 1.2rem;\n      font-weight: 700;\n      color: #fff;\n      margin-bottom: 6px;\n    }\n\n    .phase-body p {\n      font-size: 0.95rem;\n      color: var(--fg-muted);\n      line-height: 1.6;\n      margin-bottom: 8px;\n    }\n\n    .phase-deliverables {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 8px;\n      margin-top: 8px;\n    }\n\n    .phase-pill {\n      font-family: var(--font-mono);\n      font-size: 0.78rem;\n      background: rgba(255, 255, 255, 0.04);\n      border: 1px solid rgba(255, 255, 255, 0.1);\n      color: #cbd5e1;\n      padding: 4px 10px;\n      border-radius: 6px;\n    }\n\n    /* Sephirot Engine Grid */\n    .sephirot-box {\n      background: var(--bg-card);\n      border: 1px solid var(--border);\n      border-radius: 14px;\n      padding: clamp(20px, 3vw, 32px);\n      margin: 32px 0;\n    }\n\n    .sephirot-header {\n      text-align: center;\n      margin-bottom: 24px;\n    }\n\n    .sephirot-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));\n      gap: 16px;\n    }\n\n    .sephira-card {\n      background: rgba(14, 18, 27, 0.85);\n      border: 1px solid var(--border);\n      border-radius: 10px;\n      padding: 16px;\n      display: flex;\n      flex-direction: column;\n      gap: 8px;\n      transition: all 0.2s;\n    }\n\n    .sephira-card:hover {\n      border-color: var(--accent-purple);\n      transform: translateY(-2px);\n    }\n\n    .sephira-tag {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n    }\n\n    .sephira-level {\n      font-family: var(--font-mono);\n      font-size: 0.72rem;\n      color: var(--accent-purple);\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n    }\n\n    .sephira-title {\n      font-family: var(--font-display);\n      font-size: 1.1rem;\n      font-weight: 700;\n      color: #fff;\n    }\n\n    .sephira-desc {\n      font-size: 0.86rem;\n      color: var(--fg-muted);\n      line-height: 1.5;\n    }\n\n    .sephira-model {\n      font-family: var(--font-mono);\n      font-size: 0.75rem;\n      color: var(--accent-cyan);\n      margin-top: auto;\n    }\n\n    @media (max-width: 768px) {\n      .matrix-search-box input { width: 100%; }\n    }\n  \n\n/* Zero-latency language visibility rules */\n.t-ru, .t-uk, .t-en {\n  display: none !important;\n}\nhtml[data-lang="ru"] .t-ru {\n  display: revert !important;\n}\nhtml[data-lang="uk"] .t-uk {\n  display: revert !important;\n}\nhtml[data-lang="en"] .t-en {\n  display: revert !important;\n}\nhtml:not([data-lang]) .t-ru {\n  display: revert !important;\n}\n\nhtml[data-lang="ru"] span.t-ru, html[data-lang="uk"] span.t-uk, html[data-lang="en"] span.t-en, html:not([data-lang]) span.t-ru {\n  display: inline !important;\n}\nhtml[data-lang="ru"] div.t-ru, html[data-lang="uk"] div.t-uk, html[data-lang="en"] div.t-en, html:not([data-lang]) div.t-ru {\n  display: block !important;\n}\nhtml[data-lang="ru"] p.t-ru, html[data-lang="uk"] p.t-uk, html[data-lang="en"] p.t-en, html:not([data-lang]) p.t-ru {\n  display: block !important;\n}\nhtml[data-lang="ru"] tr.t-ru, html[data-lang="uk"] tr.t-uk, html[data-lang="en"] tr.t-en, html:not([data-lang]) tr.t-ru {\n  display: table-row !important;\n}\nhtml[data-lang="ru"] td.t-ru, html[data-lang="uk"] td.t-uk, html[data-lang="en"] td.t-en, html:not([data-lang]) td.t-ru {\n  display: table-cell !important;\n}\nhtml[data-lang="ru"] th.t-ru, html[data-lang="uk"] th.t-uk, html[data-lang="en"] th.t-en, html:not([data-lang]) th.t-ru {\n  display: table-cell !important;\n}\n\n/* Sticky Navigation & Top Control Toolbar */\n.top-nav {\n  position: sticky;\n  top: 0;\n  z-index: 1000;\n  backdrop-filter: blur(16px);\n  -webkit-backdrop-filter: blur(16px);\n  background: rgba(7, 9, 14, 0.90);\n  border-bottom: 1px solid var(--border);\n  padding: 12px clamp(16px, 4vw, 32px);\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 16px;\n  flex-wrap: wrap;\n}\n\n.brand-title {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  font-family: var(--font-mono);\n  font-weight: 700;\n  font-size: clamp(0.85rem, 1.2vw, 1.05rem);\n  letter-spacing: 0.08em;\n  color: #fff;\n  text-decoration: none;\n}\n.brand-title .logo-gem {\n  color: var(--accent);\n  text-shadow: 0 0 10px rgba(0, 230, 118, 0.6);\n}\n\n.top-controls {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  flex-wrap: wrap;\n}\n\n.cluster-status-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  background: rgba(0, 230, 118, 0.08);\n  border: 1px solid var(--border-accent);\n  color: var(--accent);\n  padding: 5px 12px;\n  border-radius: 20px;\n  font-family: var(--font-mono);\n  font-size: 0.72rem;\n  letter-spacing: 0.04em;\n}\n.pulse-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: var(--accent);\n  box-shadow: 0 0 8px var(--accent);\n  animation: pulseDot 2s infinite ease-in-out;\n}\n@keyframes pulseDot {\n  0%, 100% { opacity: 1; transform: scale(1); }\n  50% { opacity: 0.4; transform: scale(0.85); }\n}\n\n/* Language Switcher */\n.lang-switcher {\n  display: inline-flex;\n  align-items: center;\n  background: rgba(20, 26, 40, 0.8);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  padding: 3px;\n  gap: 2px;\n}\n.lang-btn {\n  background: transparent;\n  border: none;\n  color: var(--fg-muted);\n  font-family: var(--font-mono);\n  font-size: 0.76rem;\n  font-weight: 700;\n  padding: 5px 11px;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n}\n.lang-btn:hover {\n  color: #fff;\n  background: rgba(255, 255, 255, 0.06);\n}\n.lang-btn.active {\n  background: var(--accent);\n  color: #07090e;\n  box-shadow: 0 0 12px rgba(0, 230, 118, 0.4);\n}\n\n/* Accordion Controls */\n.accordion-controls {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n}\n.btn-accordion-toggle {\n  background: rgba(20, 26, 40, 0.8);\n  border: 1px solid var(--border);\n  color: var(--fg-muted);\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n  font-weight: 600;\n  padding: 5px 12px;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n}\n.btn-accordion-toggle:hover {\n  color: var(--cyan);\n  border-color: var(--border-cyan);\n  background: rgba(0, 229, 255, 0.08);\n}\n\n/* Level 1 Accordion: Major Sections */\ndetails.accordion-section {\n  border: 1px solid var(--border);\n  border-radius: 12px;\n  margin-bottom: 24px;\n  background: var(--bg-card);\n  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);\n  overflow: hidden;\n}\ndetails.accordion-section:hover {\n  border-color: rgba(255, 255, 255, 0.16);\n}\ndetails.accordion-section[open] {\n  border-color: var(--border-accent);\n  box-shadow: 0 0 35px rgba(0, 230, 118, 0.09);\n}\n\nsummary.accordion-summary {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: clamp(16px, 2.5vw, 22px) clamp(18px, 3vw, 28px);\n  background: rgba(14, 18, 27, 0.95);\n  cursor: pointer;\n  user-select: none;\n  list-style: none;\n  border-bottom: 1px solid transparent;\n  transition: background 0.2s, border-color 0.2s;\n}\nsummary.accordion-summary::-webkit-details-marker {\n  display: none;\n}\ndetails.accordion-section[open] > summary.accordion-summary {\n  border-bottom-color: var(--border);\n  background: rgba(18, 24, 38, 0.98);\n}\n.summary-left {\n  display: flex;\n  align-items: center;\n  gap: clamp(10px, 1.8vw, 16px);\n  flex: 1;\n}\n.summary-chevron {\n  font-family: var(--font-mono);\n  font-size: 1.15rem;\n  color: var(--accent);\n  transition: transform 0.3s ease;\n  display: inline-block;\n  width: 18px;\n  text-align: center;\n}\ndetails.accordion-section[open] > summary.accordion-summary .summary-chevron {\n  transform: rotate(90deg);\n}\n.summary-num {\n  font-family: var(--font-mono);\n  font-size: clamp(0.85rem, 1.3vw, 1.05rem);\n  font-weight: 700;\n  color: var(--accent);\n  background: rgba(0, 230, 118, 0.1);\n  border: 1px solid var(--border-accent);\n  padding: 4px 10px;\n  border-radius: 6px;\n  letter-spacing: 0.05em;\n  flex-shrink: 0;\n}\n.summary-title {\n  font-family: var(--font-display);\n  font-size: clamp(1.1rem, 1.9vw, 1.5rem);\n  font-weight: 700;\n  color: #fff;\n  margin: 0;\n  line-height: 1.35;\n}\n.summary-badge {\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n  padding: 4px 12px;\n  border-radius: 20px;\n  background: rgba(255, 255, 255, 0.05);\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  color: var(--fg-muted);\n  white-space: nowrap;\n}\n\n.accordion-content {\n  padding: clamp(20px, 3vw, 32px);\n}\n\n/* Level 2 Accordion: Subsections */\ndetails.sub-accordion {\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  border-radius: 8px;\n  margin: 16px 0;\n  background: rgba(10, 14, 22, 0.55);\n  transition: all 0.25s ease;\n  overflow: hidden;\n}\ndetails.sub-accordion:hover {\n  border-color: rgba(255, 255, 255, 0.16);\n}\ndetails.sub-accordion[open] {\n  border-color: var(--border-cyan);\n  background: rgba(13, 18, 29, 0.75);\n}\nsummary.sub-summary {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 13px 18px;\n  cursor: pointer;\n  user-select: none;\n  list-style: none;\n  background: rgba(16, 22, 34, 0.6);\n  border-bottom: 1px solid transparent;\n  transition: background 0.2s;\n}\nsummary.sub-summary::-webkit-details-marker {\n  display: none;\n}\ndetails.sub-accordion[open] > summary.sub-summary {\n  border-bottom-color: rgba(255, 255, 255, 0.06);\n  background: rgba(20, 28, 44, 0.85);\n}\n.sub-summary-left {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  flex: 1;\n}\n.sub-chevron {\n  font-family: var(--font-mono);\n  font-size: 0.95rem;\n  color: var(--cyan);\n  transition: transform 0.25s ease;\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\ndetails.sub-accordion[open] > summary.sub-summary .sub-chevron {\n  transform: rotate(90deg);\n}\n.sub-icon {\n  font-size: 1.15rem;\n  line-height: 1;\n}\n.sub-title {\n  font-family: var(--font-display);\n  font-size: clamp(0.95rem, 1.4vw, 1.18rem);\n  font-weight: 600;\n  color: var(--fg);\n  margin: 0;\n}\n.sub-badge {\n  font-family: var(--font-mono);\n  font-size: 0.7rem;\n  padding: 3px 9px;\n  border-radius: 12px;\n  background: rgba(0, 229, 255, 0.08);\n  border: 1px solid rgba(0, 229, 255, 0.25);\n  color: var(--cyan);\n}\n.sub-content {\n  padding: 18px 20px;\n}\n\n\n/* Q&A Structure Styling */\n.qa-block {\n  background: rgba(255, 255, 255, 0.02);\n  border-left: 3px solid var(--accent);\n  padding: 14px 18px;\n  border-radius: 0 8px 8px 0;\n  margin-bottom: 16px;\n}\n.qa-q {\n  font-size: 1.05rem;\n  font-weight: 700;\n  color: #fff;\n  margin-bottom: 8px;\n  line-height: 1.4;\n}\n.qa-a {\n  font-size: 0.95rem;\n  line-height: 1.6;\n  color: var(--fg);\n}\n\n/* Tetraktys Tier Layout */\n.tetraktys-container {\n  margin: 20px 0;\n  display: flex;\n  flex-direction: column;\n  gap: 18px;\n}\n.tetraktys-tier-block {\n  background: rgba(14, 18, 27, 0.6);\n  border: 1px solid rgba(255, 255, 255, 0.06);\n  border-radius: 12px;\n  padding: 16px 20px;\n}\n.tier-heading {\n  font-family: var(--font-mono);\n  font-size: 0.8rem;\n  font-weight: 700;\n  letter-spacing: 0.06em;\n  color: var(--accent);\n  margin-bottom: 14px;\n  text-transform: uppercase;\n}\n/* ===== TOC mindmap + header accordion (added) ===== */\n.toolbar-accordion {\n  background: rgba(14,18,27,0.6);\n  border: 1px solid var(--border, rgba(255,255,255,0.1));\n  border-radius: 10px;\n  margin: 12px auto;\n  max-width: 1200px;\n  overflow: hidden;\n}\n.toolbar-accordion summary.toolbar-summary {\n  cursor: pointer;\n  padding: 12px 18px;\n  font-weight: 600;\n  font-size: 0.95em;\n  letter-spacing: 0.04em;\n  list-style: none;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  color: var(--fg, #e6edf3);\n  background: rgba(255,255,255,0.04);\n  user-select: none;\n}\n.toolbar-accordion summary.toolbar-summary::-webkit-details-marker { display: none; }\n.toolbar-accordion summary.toolbar-summary::after { content: "▾"; margin-left: auto; transition: transform .2s; }\n.toolbar-accordion[open] summary.toolbar-summary::after { transform: rotate(180deg); }\n.toc-mindmap .toc-mindmap-tree { list-style: none; margin: 0; padding: 0 4px; display: grid; gap: 6px; }\n.toc-mindmap .toc-mindmap-tree ul { list-style: none; margin: 6px 0 6px 18px; padding-left: 14px; border-left: 1px dashed rgba(255,255,255,0.15); display: grid; gap: 4px; }\n.toc-mindmap .toc-mindmap-tree li { margin: 0; }\n.toc-mindmap .toc-mindmap-tree a { display: inline-flex; align-items: center; gap: 8px; color: inherit; text-decoration: none; padding: 5px 10px; border-radius: 8px; background: rgba(255,255,255,0.03); transition: background .15s; width: 100%; box-sizing: border-box; }\n.toc-mindmap .toc-mindmap-tree a:hover { background: rgba(0,230,118,0.12); text-decoration: none; }\n.toc-mindmap .toc-node-num { font-family: ui-monospace, monospace; opacity: 0.6; font-size: 0.8em; }\n.toc-mindmap .toc-sub-item a { font-size: 0.92em; padding-left: 14px; }\n.toc-toplink { text-decoration: none; color: #00e676; }\n@media (max-width: 768px) {\n  .kpi-table, .comparison-table { display: block; overflow-x: auto; }\n  .infographic-panel { overflow-x: auto; }\n  .sub-content, .accordion-content { overflow-x: auto; }\n}\n    /* Module Box fieldset/legend */\n    fieldset.module-box {\n      border: 1px solid var(--border-accent);\n      border-radius: 12px;\n      padding: 0;\n      margin: 18px 0;\n      background: var(--bg-card);\n      overflow: hidden;\n    }\n    legend.module-title {\n      padding: 8px 16px;\n      font-family: var(--font-display);\n      font-size: clamp(1rem, 1.5vw, 1.2rem);\n      font-weight: 700;\n      color: var(--accent-green);\n      background: rgba(0, 230, 118, 0.08);\n      border: 1px solid var(--border-accent);\n      border-radius: 8px;\n      margin: 12px;\n      box-shadow: 0 2px 8px rgba(0, 230, 118, 0.15);\n    }\n    /* Smooth scroll */\n    html { scroll-behavior: smooth; }\n    details.accordion-section, details.sub-accordion { scroll-margin-top: 20px; }\n\n    /* Anti-overflow hardening: additive, non-aggressive */    /* Anti-overflow hardening: additive, non-aggressive */\n    img, picture, video, canvas, svg { max-width: 100%; height: auto; }\n    table { max-width: 100%; }\n    .kpi-table, .comparison-table, .table-responsive, .table-container, table { display: block; overflow-x: auto; }\n    .accordion-content, .sub-content, .infographic-panel, .panel, .table-responsive { min-width: 0; overflow-wrap: anywhere; word-break: break-word; }\n    .diagram-canvas, .ascii-diagram, pre, code { white-space: pre-wrap; word-break: break-word; max-width: 100%; }\n\n'